#!/usr/bin/env python3
"""Gate the published live testnet artifact's exact bytes, without building Rust."""

import hashlib
from pathlib import Path
import sys


# Recorded from the approved published artifact, never generated by a build.
# An approved relaunch must update this pin, the genesis tests and provenance
# together with the artifact; an upstream file change alone is not activation.
EXPECTED_SHA256 = "0aeeddaf5b546a491d96c35fd636614c6ab42d4e5d9724126182b52c8c694ad4"
SPEC_PATH = Path(__file__).resolve().parent.parent / "chain-specs/aglais-network.json"


def main():
    try:
        actual = hashlib.sha256(SPEC_PATH.read_bytes()).hexdigest()
    except OSError as error:
        sys.exit(f"live testnet spec gate: cannot read artifact: {error}")
    if actual != EXPECTED_SHA256:
        sys.exit(
            f"live testnet spec gate: SHA-256 mismatch: expected {EXPECTED_SHA256}, got {actual}"
        )
    print(f"live testnet spec gate: PASS ({actual})")


if __name__ == "__main__":
    main()
